46	const PROCESSING_FEE = 5;
47	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
48	const LOYALTY_DISCOUNT_RATE = 0.2;
49	const LOYALTY_YEARS_THRESHOLD = 2;
50	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
51	const CURSE_SURCHARGE_RATE = 0.5;
52	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
53	const HIGH_ENCHANTMENT_THRESHOLD = 5;
54	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	  moonstone: 25,
61	};
62	const ALIKE_BLOCK_SIZE = 3;
63	const ALIKE_BLOCK_PREMIUM = 60;
64	const DEDUCTIBLE = 100;
65	
66	// Premiums are rounded up to whole G, in the MHPCO's favor.
67	const roundPremiumInFavorOfMHPCO = (amount: number): number => Math.ceil(amount);
68	
69	const countByType = (items: Item[]): Map<string, number> =>
70	  items.reduce(
71	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
72	    new Map<string, number>(),
73	  );
74	
75	// Exactly three alike items form a discounted block; any other count is priced per item.
76	const alikeItemsPremium = (type: string, count: number): number =>
77	  count === ALIKE_BLOCK_SIZE
78	    ? ALIKE_BLOCK_PREMIUM
79	    : count * BASE_PREMIUM_BY_TYPE[type];
80	
81	const policyBasePremium = (items: Item[]): number =>
82	  [...countByType(items)].reduce(
83	    (sum, [type, count]) => sum + alikeItemsPremium(type, count),
84	    0,
85	  );
86	
87	// Item-specific modifiers apply to the affected item's own base premium.
88	interface ItemRiskModifier {
89	  appliesTo: (item: Item) => boolean;
90	  rate: number;
91	}
92	
93	const ITEM_RISK_MODIFIERS: ItemRiskModifier[] = [
94	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
95	  {
96	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
97	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
98	  },
99	];
100	
101	const itemRiskSurchargeRate = (item: Item): number =>
102	  ITEM_RISK_MODIFIERS.filter((modifier) => modifier.appliesTo(item)).reduce(
103	    (rate, modifier) => rate + modifier.rate,
104	    0,
105	  );
106	
107	const itemRiskSurcharges = (items: Item[]): number =>
108	  items.reduce(
109	    (sum, item) =>
110	      sum + BASE_PREMIUM_BY_TYPE[item.type] * itemRiskSurchargeRate(item),
111	    0,
112	  );
113	
114	// Policy-wide modifiers apply to the policy base premium as a whole.
115	const loyaltyDiscountRate = (yearsWithMHPCO: number): number =>
116	  yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD ? LOYALTY_DISCOUNT_RATE : 0;
117	
118	const policyWideAdjustments = (
119	  basePremium: number,
120	  yearsWithMHPCO: number,
121	  isFollowUpContract: boolean,
122	): number =>
123	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE -
124	  basePremium * loyaltyDiscountRate(yearsWithMHPCO) -
125	  (isFollowUpContract ? basePremium * FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0);
126	
127	const quotePremium = (
128	  items: Item[],
129	  yearsWithMHPCO: number,
130	  isFollowUpContract: boolean,
131	): number => {
132	  const basePremium = policyBasePremium(items);
133	  return roundPremiumInFavorOfMHPCO(
134	    basePremium +
135	      itemRiskSurcharges(items) +
136	      policyWideAdjustments(basePremium, yearsWithMHPCO, isFollowUpContract) +
137	      PROCESSING_FEE,
138	  );
139	};
140	
141	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
142	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
143	
144	// The deductible is charged once per damaged item, not once per claim.
145	const damagePayout = (damage: Damage, insuredItems: Item[]): number => {
146	  const insuredItem = insuredItems.find((item) => item.type === damage.itemType);
147	  const reimbursementRate =
148	    (insuredItem?.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
149	      ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
150	      : 1;
151	  return damage.amount * reimbursementRate - DEDUCTIBLE;
152	};
153	
154	const claimPayout = (damages: Damage[], insuredItems: Item[]): number =>
155	  damages.reduce((sum, damage) => sum + damagePayout(damage, insuredItems), 0);
156	
157	const settleClaim = (step: ClaimStep, steps: Step[]): ClaimResult => {
158	  const policy = steps[step.policy] as QuoteStep;
159	  return {
160	    payout: claimPayout(step.incident.damages, policy.items),
161	    remainingCap: 0,
162	  };
163	};
164	
165	const issueQuote = (
166	  step: QuoteStep,
167	  yearsWithMHPCO: number,
168	  isFollowUpContract: boolean,
169	): QuoteResult => ({
170	  premium: quotePremium(step.items, yearsWithMHPCO, isFollowUpContract),
171	});
172	
173	// Every contract after the customer's first one in the scenario is a follow-up.
174	const isFollowUpContract = (stepIndex: number): boolean => stepIndex > 0;
175	
176	export const runScenario = (scenario: Scenario): ScenarioResult => {
177	  const { yearsWithMHPCO } = scenario.customer;
178	  const results = scenario.steps.map((step, index): StepResult =>
179	    step.op === "claim"
180	      ? settleClaim(step, scenario.steps)
181	      : issueQuote(step, yearsWithMHPCO, isFollowUpContract(index)),
182	  );
183	  return { results };
184	};
